import React, { useState, useContext, useEffect } from "react";
import PaymentsIcon from "@mui/icons-material/Payments";
import { DashboardContext } from "../Dashboard";
import API_URL from "../../../config/api";
import dayjs from "dayjs";
import { Table, Tag, Modal } from "antd";
import numberFormat from "../../../Function/NumberFormat2float";
import ErrorMessage from "../../../Toast/ErrorMessage";
import { OutlinedInput, TextField, Pagination } from "@mui/material";
import Swal from "sweetalert2";
import Lottie from "lottie-react";

import success_ani from "../../../Json/success_ani.json";
import money_more_ani from "../../../Json/money_more.json";
import withdraw_ani from "../../../Json/withdraw_icon.json";
import loading_ani from "../../../Json/loading_animetion4.json";
import pinerror_ani from "../../../Json/Alert.json";
import OpenNotification from "../../../Toast/OpenNotification";
import { useWebSocket } from "../WebSocketUser";
import { useTranslation } from "react-i18next";
import { TOKEN_KEY } from "../../../config/token_key";
import Loading from "../../../Toast/LoadingScreen";
import FolderOffIcon from "@mui/icons-material/FolderOff";
import AssuredWorkloadIcon from "@mui/icons-material/AssuredWorkload";
import ArrowOutwardIcon from '@mui/icons-material/ArrowOutward';
function Withdraw({ userdata }) {
  const { t } = useTranslation();

  const { sendMessage } = useWebSocket();
  const { get_user } = useContext(DashboardContext);
  const [allcredit, setAllcredit] = useState([]);
  const [allcreditmobile, setAllcreditmobile] = useState([]);
  const [allcreditBackup, setAllcreditBackup] = useState([]);
  const [allLoading, setAllLoading] = useState(false);
  const [amount, setAmount] = useState("");
  const [isConfirm, setIsConfirm] = useState(false);

  const [msgErr1, setMsgErr1] = useState("");
  const [userId] = useState(localStorage.getItem(`${TOKEN_KEY}Id`));

  const [page, setPage] = useState(1);
  const [pageCount, setPageCount] = useState(1);
  const itemcount = 10;

  const [timestart, setTimestart] = useState(
    dayjs().startOf("month").format("YYYY-MM-DD")
  );
  const [timeend, setTimeend] = useState(
    dayjs().endOf("month").format("YYYY-MM-DD")
  );
  const [inputSearch, setInputSearch] = useState("");
  const timeFormat = (time) => {
    return dayjs(time).format("YYYY-MM-DD");
  };
  const handleChangePage = (event, value) => {
    setPage(value);
    if (value > 1) {
      setAllcreditmobile(
        allcreditBackup.slice((value - 1) * itemcount, itemcount * value)
      );
    } else {
      setAllcreditmobile(allcreditBackup.slice(0, itemcount));
    }
    window.scrollTo(0, 0);
  };

  const changDatestart = (e) => {
    if (e.target.value >= timeend) {
      setTimestart(dayjs(timeend).add(-1, "day").format("YYYY-MM-DD"));
    } else {
      setTimestart(e.target.value);
    }
  };
  const changDateend = (e) => {
    if (e.target.value <= timestart) {
      setTimeend(dayjs(timestart).add(1, "day").format("YYYY-MM-DD"));
    } else {
      setTimeend(e.target.value);
    }
  };
  const handleChageByDate = () => {
    setAllLoading(true);
    let data = [];
    let sumde = 0;
    let sumwith = 0;
    allcreditBackup.map((all) => {
      if (inputSearch.length === 0) {
        if (
          timeFormat(all.sliptime) >= timestart &&
          timeFormat(all.sliptime) <= timeend
        ) {
          data.push(all);
        }
      } else {
        if (
          timeFormat(all.sliptime) >= timestart &&
          timeFormat(all.sliptime) <= timeend &&
          all.people.uid === inputSearch
        ) {
          data.push(all);
        }
      }
    });

    OpenNotification({
      message: `${t("finishedsearch")}`,
      type: 1,
    });

    // แสดงข้อมูลทั้งหมดที่ค้นหาได้โดยไม่แบ่งหน้า
    setAllcreditmobile(data); // สำหรับ mobile view
    setAllcredit(data); // สำหรับ desktop view

    // รีเซ็ต pagination กลับไปหน้าแรกและอัพเดท pageCount
    setPage(1);
    setPageCount(1);

    setAllLoading(false);
  };

  useEffect(() => {
    get_AllWithdraw();
  }, []);
  const get_AllWithdraw = async () => {
    setAllcredit([]);

    await API_URL.get(`api/deposit/getOneUserWithdraw/${userId}`)
      .then((res) => {
        const getalluser = res.data;
        if (getalluser.length !== 0) {
          getalluser.map((e) => {
            e.amounttxt = e.amount.toString();
            e.sliptimetxt = dayjs(e.sliptime)
              .format("DD/MM/YYYY HH:mm")
              .toString();
          });
          setAllcredit(getalluser);
          setAllcreditBackup(getalluser);
          setAllcreditmobile(getalluser.slice(0, itemcount));
          setPageCount(
            getalluser.length / itemcount < 1
              ? 1
              : Math.ceil(getalluser.length / itemcount)
          );
        }
      })
      .catch((err) => {
        console.log(err);
      });
  };
  const columns_alluser = [
    {
      title: `${t("status")}`,
      align: "center",
      width: "8%",
      render: (allcredit) => (
        <>
          {allcredit.status === 0 ? (
            <Tag color="geekblue">
              <p className="text-xs text-white my-auto px-2 py-1 font-semibold">
                {t("waiting")}
              </p>
            </Tag>
          ) : allcredit.status === 1 ? (
            <Tag color="green">
              <p className="text-xs text-white my-auto px-2 py-1 font-semibold">
                {t("approve")}
              </p>
            </Tag>
          ) : (
            <Tag color="volcano">
              <p className="text-xs text-white my-auto px-2 py-1 font-semibold">
                {t("notapproved")}
              </p>
            </Tag>
          )}
        </>
      ),
    },

    {
      title: `${t("time")}`,
      align: "center",
      render: (allcredit) => (
        <p className=" text-xs text-white my-auto px-2">
          {dayjs(allcredit.sliptime).format("DD/MM/YYYY")}{" "}
          {dayjs(allcredit.sliptime).format("HH:mm")}
        </p>
      ),
    },
    {
      title: `${t("approvaltime")}`,
      align: "center",
      render: (allcredit) => (
        <p className=" text-xs text-white my-auto px-2">
          {allcredit.status !== 0
            ? `${dayjs(allcredit.updatedAt).format("DD/MM/YYYY HH:mm:ss")}`
            : "-"}
        </p>
      ),
    },

    {
      title: `${t("credit")}`,
      align: "center",
      render: (allcredit) => (
        <p className="wsn text-xs text-white my-auto px-2">
          {numberFormat(allcredit.amount)}
        </p>
      ),
    },
    {
      title: `${t("oldamount")}`,
      align: "center",
      render: (allcredit) => (
        <p className="wsn text-xs text-white my-auto px-2">
          {numberFormat(allcredit.preamount)}
        </p>
      ),
    },
    {
      title: `${t("balance")}`,
      align: "center",
      render: (allcredit) => (
        <>
          <Tag color="orange">
            <p className="text-xs text-white my-auto px-2 py-1 font-semibold">
              {numberFormat(allcredit.net)}
            </p>
          </Tag>
        </>
      ),
    },
    {
      title: `${t("note")}`,
      align: "center",
      width: "30%",
      render: (allcredit) => (
        <p className="text-xs text-white my-auto  text-hover-show">
          {allcredit.note}
        </p>
      ),
    },
  ];

  const CreateWithdraw = async () => {
    if (userdata.idbank === 0) {
      Swal.fire({
        background: "#1b1d2c",
        title: `<strong class="text-white">${t("nobankaccount")}</strong>`,
        icon: "warning",
        html: `<span class="text-white">${t("linkyourbankaccount")}</span>`,
        showCloseButton: true,
        focusConfirm: false,
        confirmButtonColor: "#17826c",
        confirmButtonText:
          `<a  rel="noopener noreferrer" href="/login/account" class="mx-auto flex justify-center text-white asty1">` +
          " <button>" +
          `>&emsp;${t("gotobank")}</button></a>`,
        confirmButtonAriaLabel: "Thumbs up, great!",
        cancelButtonAriaLabel: "Thumbs down",
        
      });
      return;
    }
    if (amount === 0 || Number(amount) === 0 || amount === "0") {
      setMsgErr1(`${t("enter_the_correct_amount")}`);
      return;
    }
    setMsgErr1("");
    if (amount > userdata.credit) {
      setMsgErr1(`${t("insufficientwithdrawalamount")}`);
      return;
    }
    setMsgErr1("");
    setIsConfirm(!isConfirm);
  };
  const ConfirmWithdraw = async () => {
    setIsConfirm(!isConfirm);
    let secondsToGo = 6;
    const modal = Modal.info({
      wrapClassName: "custom-modal-background",
      title: "",
      okButtonProps: {
        disabled: true,
        className: "modal-footer-hiden-button hidden",
      },
      content: (
        <div className="w-full mx-auto -ml-3 ">
          {" "}
          <Lottie
            animationData={loading_ani}
            loop={true}
            className="w-2/5 mx-auto "
          />
          <p className="text-center text-base font-semibold my-2 text-white">
            {t("inprogress")}
          </p>
        </div>
      ),
    });
    const timer = setInterval(async () => {
      secondsToGo -= 1;

      if (secondsToGo === 3) {
        await API_URL.post(`api/deposit/addWithdraw`, {
          peopleId: userdata.id,
          amount: amount,
          // pincode: pincode,
        })
          .then(() => {
            modal.update({
              wrapClassName: "custom-modal-background",
              title: "",
              
              content: (
                <div className="w-full mx-auto -ml-3">
                  {" "}
                  <Lottie
                    animationData={success_ani}
                    loop={false}
                    className="w-2/5 mx-auto "
                  />
                  <p className="text-center text-base font-semibold my-2 text-white">
                    {t("waitingforadminapproval")}
                  </p>
                </div>
              ),
            });
            setTimeout(() => {
              get_user();
              modal.destroy();
              get_AllWithdraw();
              sendMessage({ type: "refreshUserWithdraw" });
            }, 4000);
          })
          .catch((err) => {
            err.response.data.status === 402
              ? modal.update({
                wrapClassName: "custom-modal-background",
                  title: "",
                  content: (
                    <div className="w-full mx-auto -ml-3">
                      <Lottie
                        animationData={pinerror_ani}
                        loop={false}
                        className="w-2/5 mx-auto "
                      />
                      <p className="text-center text-base font-semibold my-2">
                        รหัส PIN ไม่ถูกต้อง
                      </p>
                    </div>
                  ),
                })
              : err.response.data.status === 401
              ? modal.update({
                wrapClassName: "custom-modal-background",
                  title: "",
                  content: (
                    <div className="w-full mx-auto -ml-3">
                      <Lottie
                        animationData={money_more_ani}
                        loop={false}
                        className="w-2/5 mx-auto "
                      />
                      <p className="text-center text-base font-semibold my-2 text-white">
                        {t("insufficientwithdrawalamount")}
                      </p>
                    </div>
                  ),
                })
              : err.response.data.status === 400
              ? modal.update({
                wrapClassName: "custom-modal-background",
                  title: "",
                  content: (
                    <div className="w-full mx-auto -ml-3">
                      <Lottie
                        animationData={pinerror_ani}
                        loop={false}
                        className="w-2/5 mx-auto "
                      />
                      <p className="text-center text-base font-semibold my-2 text-white">
                        {t("withdrawalspendingapproval")}
                      </p>
                    </div>
                  ),
                })
              : OpenNotification({
                  message: `${t("data_transmission_error")}`,
                  type: 4,
                });
            setTimeout(() => {
              setAmount(0);
              modal.destroy();
            }, 3000);
          });
      }
    }, 1000);

    setTimeout(() => {
      clearInterval(timer);
    }, secondsToGo * 1000);
  };
  return (
    <div>
      <Modal
        title=""
        open={isConfirm}
        onCancel={() => setIsConfirm(!isConfirm)}
        footer={null}
      >
        <div className="flex justify-center ">
          <Lottie className="w-1/2" animationData={withdraw_ani} loop={true} />
        </div>

        <div className="flex justify-center">
          <button
            onClick={ConfirmWithdraw}
            type="button"
            className="text-white bg-gradient-to-r from-green-400 via-green-500 to-green-600 hover:bg-gradient-to-br focus:ring-4 focus:outline-none focus:ring-green-300 dark:focus:ring-green-800 font-medium rounded-lg text-sm px-5 py-2.5 text-center mr-2 mb-2"
          >
            {t("confirm_withdrawal")}
          </button>
          <button
            onClick={() => setIsConfirm(!isConfirm)}
            type="button"
            className="text-white bg-gradient-to-r hover:bg-red-400  border-gray-500 hover:bg-gradient-to-br focus:ring-4 focus:outline-none  font-medium rounded-lg text-sm px-5 py-2.5 text-center mr-2 mb-2"
          >
            {t("cancel")}
          </button>
        </div>
      </Modal>
      <div className="w-full lg:w-1/3 grid grid-cols-1 justify-center mx-auto bg-[#1B1C2C] py-2 px-5 rounded-md">
        <div className=" mb-2 items-center w-full  ">
          <div className="w-full  mx-0 lg:mx-2 my-2">
            <p className="flex justify-start  text-base my-auto text-white">
              {t("amount_to_withdraw")}
            </p>
          </div>
          <div className="flex relative w-full lg:w-full">
            <OutlinedInput
              value={amount}
              placeholder="0"
              onChange={(e) => setAmount(e.target.value)}
              className="block w-full  text-white placeholder-gray-400 bg-[#22242F] border border-gray-200 rounded-md   "
              aria-describedby="outlined-weight-helper-text"
              onKeyPress={(e) => !/[0-9.]/.test(e.key) && e.preventDefault()}
              autoComplete="off"
              fullWidth
              inputProps={{
                maxLength: 10,
                style: { color: "white", colorScheme: "dark" },
              }}
            />
            <div className="absolute right-2  bottom-0 top-0 flex items-center">
              <p className="my-auto text-xl font-medium ">USDT</p>
            </div>
          </div>
          <div className="flex flex-wrap align-bottom items-end w-full mt-2">
            {msgErr1 ? (
              <ErrorMessage message={msgErr1} className="w-full" />
            ) : (
              <></>
            )}
            <button
              onClick={CreateWithdraw}
              className="text-center text-black font-semibold  w-full h-11 lg:h-11 rounded-md bg-white hover:bg-teal-50 shadow-md border-[1px] border-[#7ecec3]"
              // style={{textShadow:"0px 1px 2px black"}}
            >
              <ArrowOutwardIcon fontSize="small" className="mr-1" />
              {t("withdraw")}
            </button>
          </div>
        </div>
      </div>

      <div>
        <div className="w-full">
          <div className="w-full px-1 md:px-8">
            {/* <ul
              className="flex mb-0 list-none  pt-3 pb-0 flex-row "
              role="tablist"
            >
              <li className="-mb-px mr-2 last:mr-0 flex-auto text-center ">
                <a className="text1line text-sm md:text-md font-bold uppercase px-2 py-2 lg:py-4 shadow-lg rounded-t-lg bg-teal-500  block leading-normal text-white border-teal-700 border-2"
                style={{textShadow:"0px 1px 2px black"}}
                >
                  <PaymentsIcon className="mr-2" />
                  {t("withdrawal_history")}
                </a>
              </li>
            </ul> */}
             <div className="px-3 pb-0.5">
        <div className="flex  items-center text-white mt-2">
          <PaymentsIcon className="text-left mr-2" />
          <p className="text-xs lg:text-sm">{t("withdrawal_history")}</p>
        </div>

        <div className="mt-0.5 h-0.5 bg-teal-500 w-2/4"></div>
      </div>
            {/* <div className="h-1 bg-teal-500"></div> */}
            <div className="w-full  mt-2 flex flex-wrap justify-center  bg-[#2B405D]  py-3 px-1 mx-auto rounded-lg">
              <div className="w-1/2 md:w-1/5 px-1  rounded-md">
                <TextField
                  inputProps={{ style: { color: "white",colorScheme:"dark" } }}
                  // inputProps={{ style: { color: "black" } }}
                  id="date"
                  label={t("start")}
                  type="date"
                  size="small"
                  value={timestart}
                  onChange={(e) => changDatestart(e)}
                  InputLabelProps={{
                    shrink: true,
                    style: { color: "#fff" },
                  }}
                  fullWidth
                />
              </div>
              <div className="w-1/2 md:w-1/5 px-1  rounded-md">
                <TextField
                   inputProps={{ style: { color: "white",colorScheme:"dark" } }}
                  // inputProps={{ style: { color: "black" } }}
                  id="date"
                  label={t("end")}
                  type="date"
                  size="small"
                  fullWidth
                  value={timeend}
                  onChange={(e) => changDateend(e)}
                  InputLabelProps={{
                    shrink: true,
                    style: { color: "#fff" },
                  }}
                />
              </div>

              <button
                onClick={handleChageByDate}
                className="w-2/3 lg:w-1/12 my-1 md:my-0 px-4 py-1 bg-teal-600 hover:bg-teal-800 rounded-md shadow-lg text-white wsn"
              >
                {t("search")}
              </button>
            </div>
            <div className="relative  flex-col min-w-0 break-words  w-full mb-6  hidden lg:flex">
              <div className="px-0.5 lg:px-1 py-1 flex-auto">
                <div className="tab-content tab-space">
                  <div className="block">
                    <Table
                      className="table-striped-rows my-1"
                      size="middle"
                      scroll={{
                        x: 800,
                      }}
                      pagination={{ pageSize: 10 }}
                      rowKey="id"
                      columns={columns_alluser}
                      dataSource={allcredit}
                    />
                  </div>
                </div>
              </div>
            </div>
            <div className="relative flex-col min-w-0 break-words  w-full mb-6  flex lg:hidden">
              {allLoading ? (
                <Loading></Loading>
              ) : (
                <>
                  {allcreditmobile.length !== 0 ? (
                    <>
                      {allcreditmobile.map((data, index) => (
                        <div
                          className=" bg-[#2B405D] rounded-lg py-2 my-1 px-3 text-xs lg:text-sm shadow-md"
                          key={index}
                        >
                          <div className="flex justify-between">
                            <p className="w-1/3">{t("withdraw")} </p>
                            <p className="font-semibold w-1/3 text-center">
                              {" "}
                              {numberFormat(data.amount)}{" "}
                            </p>
                            <div className="flex justify-end w-1/3">
                              <div>
                                {data.status === 0 ? (
                                  <Tag color="geekblue">
                                    <p className="text-xs text-white my-auto px-2 py-1 font-semibold">
                                      {t("waiting")}
                                    </p>
                                  </Tag>
                                ) : data.status === 1 ? (
                                  <Tag color="green">
                                    <p className="text-xs text-white my-auto px-2 py-1 font-semibold">
                                      {t("approve")}
                                    </p>
                                  </Tag>
                                ) : (
                                  <Tag color="volcano">
                                    <p className="text-xs text-white my-auto px-2 py-1 font-semibold">
                                      {t("notapproved")}
                                    </p>
                                  </Tag>
                                )}
                              </div>
                            </div>
                          </div>
                          <div className="flex justify-between my-0.5">
                            <p className=" font-semibold mr-2">{t("time")}</p>
                            <p>
                              {dayjs(data.sliptime).format(
                                "DD/MM/YYYY HH:mm:ss"
                              )}
                            </p>
                          </div>
                          <div className="flex justify-between my-0.5">
                            <p className=" font-semibold mr-2">
                              {t("approvaltime")}
                            </p>
                            <p>
                              {data.status !== 0
                                ? `${dayjs(data.updatedAt).format(
                                    "DD/MM/YYYY HH:mm:ss"
                                  )}`
                                : "-"}
                            </p>
                          </div>
                          <div className="flex justify-between align-middle my-0.5">
                            <p className="mr-2 font-semibold">{t("note")} </p>
                            <p>{data.note}</p>
                          </div>
                        </div>
                      ))}
                      <Pagination
                        count={pageCount}
                        page={page}
                        onChange={handleChangePage}
                        size="large"
                        color="primary"
                        className="flex justify-center mt-5 text-white"
                      />
                    </>
                  ) : (
                    <div className=" grid gap-2 justify-center  items-center text-center text-white m-10 mx-auto">
                      <div>
                        <FolderOffIcon className="scale-150" />
                        <p className="text-xs lg:text-base mt-3">
                          {t("nodata")}
                        </p>
                      </div>
                    </div>
                  )}
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Withdraw;
