import { useEffect, useState } from 'react';
import API_URL from "../../config/api";
import { useTranslation } from "react-i18next";
import { TOKEN_KEY } from '../../config/token_key';

const CHATWOOT_CONFIG = {
  BASE_URL: "https://app.chatwoot.com",
  // BASE_URL: "https://tnn89.pro",
  WEBSITE_TOKEN: 'smiGykmxXMDZNUN9P6nQ5dDU',
  // WEBSITE_TOKEN: 'BrWJ7SDAKjsqB9ZjHM93pS12',
  MAX_RETRIES: 3,
  RETRY_DELAY: 2000
};

const ChatwootComponent = ({ messages }) => {
  const { t } = useTranslation();
  const [hash, setHash] = useState(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const data = JSON.parse(localStorage.getItem(`${TOKEN_KEY}Userdata`));

  // สร้างฟังก์ชันสำหรับแก้ไข visibility ของ iframe
  const fixIframeVisibility = () => {
    const iframe = document.getElementById('chatwoot_live_chat_widget');
    if (iframe) {
      iframe.removeAttribute('style'); // ลบ style attribute ทั้งหมด
      // หรือถ้าต้องการเก็บ style อื่นๆ ไว้:
      // iframe.style.visibility = 'visible';
    }
  };

  // ตรวจสอบและแก้ไข iframe visibility ทุกๆ interval
  useEffect(() => {
    if (!isInitialized) return;

    const checkInterval = setInterval(() => {
      const iframe = document.getElementById('chatwoot_live_chat_widget');
      if (iframe && iframe.style.visibility === 'hidden') {
        fixIframeVisibility();
      }
    }, 1000);

    return () => clearInterval(checkInterval);
  }, [isInitialized]);

  // Generate Hash
  useEffect(() => {
    const generateHash = async () => {
      if (data?.user?.id) {
        try {
          const response = await API_URL.post(`api/admin/generate-hmac`, { 
            message: data.user.id.toString() 
          });
          setHash(response.data.hash);
        } catch (error) {
          console.error('Error generating hash:', error);
        }
      }
    };

    generateHash();
  }, [data]);

  // Initialize Chatwoot with improved visibility handling
  useEffect(() => {
    if (isInitialized) return;

    const loadChatwoot = async () => {
      try {
        const script = document.createElement("script");
        script.src = `${CHATWOOT_CONFIG.BASE_URL}/packs/js/sdk.js`;
        // script.src = `/sdk.js`;
        script.defer = true;
        script.async = true;

        script.onload = () => {
          if (typeof window.chatwootSDK !== 'undefined') {
            window.chatwootSettings = {
              hideMessageBubble: false,
              position: "right",
              locale: `${t("language_chat")}`,
              launcherTitle: "Chat with us",
            };

            window.chatwootSDK.run({
              websiteToken: CHATWOOT_CONFIG.WEBSITE_TOKEN,
              baseUrl: CHATWOOT_CONFIG.BASE_URL
            });

            // ตรวจสอบ iframe หลังจาก SDK โหลดเสร็จ
            setTimeout(() => {
              fixIframeVisibility();
              setIsInitialized(true);
            }, 1000);
          }
        };

        script.onerror = (error) => {
          console.error('Failed to load Chatwoot SDK:', error);
          setIsInitialized(false);
        };

        document.head.appendChild(script);
      } catch (error) {
        console.error('Error initializing Chatwoot:', error);
        setIsInitialized(false);
      }
    };

    loadChatwoot();

    return () => {
      const script = document.querySelector(`script[src="${CHATWOOT_CONFIG.BASE_URL}/packs/js/sdk.js"]`);
      if (script) {
        document.head.removeChild(script);
      }
      setIsInitialized(false);
    };
  }, [t]);

  // Handle Chatwoot Ready Event with visibility fix
  useEffect(() => {
    const handleChatwootReady = async () => {
      if (!window.$chatwoot) return;

      // Fix visibility on ready event
      fixIframeVisibility();

      if (data?.user) {
        try {
          window.$chatwoot.setUser(`${data.user.id}`, {
            identifier_hash: hash,
            email: data.user.email,
            name: data.user.firstname,
            phone_number: `+66${data.user.phone.substring(1)}`,
            company_name: data.user.uid
          });

          window.$chatwoot.setCustomAttributes({
            accountId: `${data.user.id}`,
            pricingPlan: "paid",
          });
        } catch (error) {
          console.error('Error setting up Chatwoot user:', error);
        }
      }
    };

    window.addEventListener("chatwoot:ready", handleChatwootReady);
    
    return () => {
      window.removeEventListener("chatwoot:ready", handleChatwootReady);
    };
  }, [data, hash]);

  return null;
};

export default ChatwootComponent;