import React from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay } from "swiper/modules";
import "swiper/css";
import carousel_img1 from "../../../image/carousel_home/caru1.jpg";
import carousel_img2 from "../../../image/carousel_home/caru2.gif";
import carousel_img3 from "../../../image/carousel_home/caru3.webp";
import carousel_img4 from "../../../image/carousel_home/caru4.gif";
import carousel_img5 from "../../../image/carousel_home/caru5.jpg";
import carousel_img6 from "../../../image/carousel_home/caru6.gif";

export default function SimpleSlider() {
  const images = [
    carousel_img1,
    carousel_img2,
    carousel_img3,
    carousel_img4,
    carousel_img5,
    carousel_img6,

  ];
  return (
<div className="w-full ">
      <Swiper
        modules={[Autoplay]}
        spaceBetween={20}
        loop={true}
        autoplay={{
          delay: 4000,
          disableOnInteraction: false,
        }}
        breakpoints={{
          0: {
            slidesPerView:1, // mobile
          },
          768: {
            slidesPerView: 3, // desktop
          },
        }}
      >
        {images.map((src, i) => (
          <SwiperSlide key={i}>
            <img
              src={src}
              alt={`slide-${i}`}
              className="rounded-xl w-full h-48 md:h-40 lg:h-80 object-cover"
            />
          </SwiperSlide>
        ))}
      </Swiper>
    </div>
  );
}
