import React, { useContext, useState, useEffect, useRef } from "react";
import dayjs from "dayjs";
import API_URL from "../../config/api";
import Swal from "sweetalert2";
import { DashboardContext } from "./Dashboard";
import { useTranslation } from "react-i18next";
import numberFormat from "../../Function/NumberFormat2float";
import { useWebSocket } from "./WebSocketUser";

const CountdownTime = ({ id, date }) => {
  const [timeLeft, setTimeLeft] = useState(date);
  const { t } = useTranslation();
  const { get_OneUserTrading, get_user } = useContext(DashboardContext);
  const alertTriggeredRef = useRef(false);
  const timeoutRef = useRef(null);
  const { sendMessage } = useWebSocket();

  const Alert_Trade = async () => {
    if (alertTriggeredRef.current) {
      return;
    }

    alertTriggeredRef.current = true;

    try {
      const res = await API_URL.post(`api/tradelist/getOneUserTradingTimeout`, {
        id: id,
      });
      const data = res.data;
      sendMessage({ type: "refreshUserTrading" });
      await Swal.fire({
        background: "#1b1d2c",
        title: `<div class="bg-gray-900 text-teal-400 py-2 rounded-sm"><strong>${data.symbol}</strong></div>`,
        html: `
          <p class="mb-2 ${
            data.trade_result === 0 ? "text-green-500" : "text-red-500"
          }">${data.trade_result === 0 ? "+" : "-"} ${data.net}</p>
          <div class="bg-[#2B405F] text-white">
            <table class="text-xs alert_table">
              <tr>
                <th>${t("buy_alert")}</th>
                <th>${t("time")}(${t("minute")})</th>
                <th>${t("opening_price")}</th>
                <th>${t("closing_price")}</th>
                <th>${t("result")}</th>
              </tr>
              <tr>
                <td class="${
                  data.type_order === 1 ? `text-green-600` : "text-red-600"
                } font-semibold">${
          data.type_order === 1 ? `${t("buy")}` : `${t("sell")}`
        }</td>
                <td>${dayjs(data.closing_time).diff(
                  data.opening_time,
                  "minute"
                )}</td>
                <td>${numberFormat(data.opening_price)}</td>
                <td>${numberFormat(data.closing_price)}</td>
                <td>${data.trade_result === 0 ? "+" : "-"} ${data.net}</td>
              </tr>
            </table>
          </div>
        `,
        focusConfirm: false,
        showDenyButton: true,
        showConfirmButton: false,
        denyButtonText: `
          <p class="m-auto text-center px-3">${t("close")}</p>
        `,
        customClass: {
          container: "p-0",
          popup: "p-1",
          title: "p-1",
          htmlContainer: "p-1 m-0 ",
          confirmButton: "w-1/4",
          footer: "p-1",
        },
      });

      get_OneUserTrading();
      get_user();
    } catch (err) {
      console.error("Alert_Trade error:", err);
      // Reset flag if there's an error
      alertTriggeredRef.current = false;
    }
  };

  useEffect(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    if (timeLeft > 0) {
      alertTriggeredRef.current = false;
    }
    if (timeLeft <= 0 && !alertTriggeredRef.current) {
      Alert_Trade();
      return;
    }

    if (timeLeft > 0) {
      timeoutRef.current = setTimeout(() => {
        setTimeLeft(timeLeft - 1);
      }, 1000);
    }

    // Cleanup
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [timeLeft]);

  return <></>;
};

export default CountdownTime;
